import XCTest

@testable import ReticulumSwift

/// Fetching a release as an `rngit` client does, measured against Python RNS 1.5.4.
///
/// Every manifest below was signed by the reference and is replayed as it
/// stands, so the port only ever reads a signature here and the randomised
/// signing the port does elsewhere never enters into it.
final class RNGitClientFetchReleaseTests: XCTestCase {

  private struct Named: Equatable {
    let name: String
    let bytes: String
  }

  /// One answer a node sends back, as the reference recorded it.
  private enum Answer {
    case file(String, String, String?)
    case bytes(String, String?)
    case none
  }

  private struct Request: Equatable {
    let path: String
    let fields: String
    let timeout: Double
    let progress: Bool
  }

  private struct Run {
    let label: String
    let remote: String?
    let target: String?
    let signer: String?
    let offline: Bool
    let hasPath: Bool
    let recalls: Bool
    let linkComesUp: Bool
    let answers: [Answer]
    let present: [Named]
    let beside: [Named]
    let folders: [String]
    let written: String
    let aborted: String?
    let exited: Int?
    let requests: [Request]
    let tornDown: Bool
    let left: [Named]
  }

  /// One report a transfer made of itself.
  private struct Report {
    let fraction: Double
    let size: Int?
    let transferSize: Int?
    let at: Double
  }

  /// One run of the transfer reporting on its own.
  private struct Progress {
    let label: String
    let indent: String
    let transfer: String
    let reports: [Report]
    let written: String
  }

  private static let when = 1_757_000_000

  private static let runs: [Run] = [
