  /// Holds what the client wrote.
  private final class Recorder: RNGitClientOutput {
    var written = ""
    func write(_ text: String) { written += text }
  }

  /// Answers a client the way one run says to, holding what it was asked.
  private final class Stub: RNGitClientTransport {
    private var answers: [Answer]
    private let vector: Run
    private let staging: String
    var requests: [Request] = []
    var tornDown = false

    init(_ vector: Run, staging: String) {
      self.vector = vector
      self.answers = vector.answers
      self.staging = staging
    }

    func mediumPathTimeout() -> TimeInterval { 1606 }

    func awaitPath(to destinationHash: Data, timeout: TimeInterval) -> Bool { vector.hasPath }

    func recallIdentity(for destinationHash: Data) -> Identity? {
      vector.recalls ? Identity() : nil
    }

    func establishLink(to identity: Identity) -> Bool { vector.linkComesUp }

    func request(
      _ path: RNGitRequestPath, _ fields: MsgPack.Value, timeout: TimeInterval,
      progress: ((RNGitTransferProgress) -> Void)?
    ) -> RNGitClientResponse {
      requests.append(
        Request(
          path: path.rawValue, fields: MsgPack.encode(fields).hexString, timeout: timeout,
          progress: progress != nil))
      guard !answers.isEmpty else { return RNGitClientResponse(result: .bytes(Data([0]))) }
      switch answers.removeFirst() {
      case .none: return RNGitClientResponse(result: .none)
      case .bytes(let body, let metadata):
        return RNGitClientResponse(
          result: .bytes(Data(pythonHex: body) ?? Data()), metadata: Self.named(metadata))
      case .file(let name, let body, let metadata):
        let served = staging + "/" + name
        FileManager.default.createFile(atPath: served, contents: Data(pythonHex: body))
        return RNGitClientResponse(result: .file(served), metadata: Self.named(metadata))
      }
    }

    func teardown() { tornDown = true }

    /// What `metadata` decodes to, or nothing where the answer carried none.
    private static func named(_ metadata: String?) -> MsgPack.Value? {
      guard let metadata, let bytes = Data(pythonHex: metadata) else { return nil }
      return try? MsgPack.decode(bytes)
    }
  }

  /// `fields` decoded and written out again, so the two encoders are compared on what they
  /// carry rather than on how each of them spells it.
  private static func normalized(_ request: Request) -> Request {
    let fields = (try? MsgPack.decode(Data(pythonHex: request.fields) ?? Data())) ?? .nil
    return Request(
      path: request.path, fields: MsgPack.encode(fields).hexString, timeout: request.timeout,
      progress: request.progress)
  }

  func testFetchingAReleaseMatchesTheReference() throws {
    let manager = FileManager.default
    for run in Self.runs {
      let root = NSTemporaryDirectory() + "rngit-fetch-" + UUID().uuidString
      let working = root + "/working"
      let staging = root + "/staging"
      let manifests = root + "/manifests"
      for directory in [working, staging, manifests] {
        try manager.createDirectory(atPath: directory, withIntermediateDirectories: true)
      }
      defer { try? manager.removeItem(atPath: root) }

      for file in run.present {
        manager.createFile(atPath: working + "/" + file.name, contents: Data(pythonHex: file.bytes))
      }
      for file in run.beside {
        manager.createFile(
          atPath: manifests + "/" + file.name, contents: Data(pythonHex: file.bytes))
      }
      for folder in run.folders {
        try manager.createDirectory(
          atPath: manifests + "/" + folder, withIntermediateDirectories: true)
      }

      let output = Recorder()
      let transport = Stub(run, staging: staging)
      let commands = RNGitClientCommands(
        now: { Date(timeIntervalSince1970: TimeInterval(Self.when)) }, workingDirectory: working,
        transport: transport, output: output)

      var aborted: String?
      var failed = false
      do {
        try commands.fetchRelease(
          remote: run.remote?.replacingOccurrences(of: "MANIFESTS/", with: manifests + "/"),
          target: run.target, signer: run.signer, offline: run.offline)
      } catch let abort as RNGitClientAbort {
        aborted = abort.message
      } catch is RNGitClientFailure {
        failed = true
      }

      let written = output.written.replacingOccurrences(
        of: manifests + "/", with: "MANIFESTS/")
      XCTAssertEqual(written, run.written, run.label)
      XCTAssertEqual(aborted, run.aborted, run.label)
      XCTAssertEqual(failed, run.exited == 1, run.label)
      XCTAssertEqual(
        transport.requests.map(Self.normalized), run.requests.map(Self.normalized), run.label)
      XCTAssertEqual(transport.tornDown, run.tornDown, run.label)

      var left: [Named] = []
      for name in (try manager.contentsOfDirectory(atPath: working)).sorted() {
        let bytes = try Data(contentsOf: URL(fileURLWithPath: working + "/" + name))
        left.append(Named(name: name, bytes: bytes.hexString))
      }
      XCTAssertEqual(left, run.left, run.label)
    }
  }

  func testReportingATransferMatchesTheReference() {
    for run in Self.progress {
      let output = Recorder()
      var reporting = RNGitTransferReporting(label: run.transfer, indent: run.indent)
      for report in run.reports {
        reporting.report(
          RNGitTransferProgress(
            fraction: report.fraction, size: report.size, transferSize: report.transferSize),
          at: TimeInterval(Self.when) + report.at, to: output)
      }
      XCTAssertEqual(output.written, run.written, run.label)
    }
  }

